package main

import (
	"fmt"
	"reflect"
	"strconv"
)

func main() {
	// Konversi numerik
	var i int = 255
	f := float64(i)
	u := uint8(i)
	fmt.Printf("int: %d, float64: %.1f, uint8: %d\n", i, f, u)

	// Truncation (bukan round)
	pi := 3.99
	piInt := int(pi)
	fmt.Printf("%.2f -> int = %d (truncated!)\n", pi, piInt)

	// strconv
	s := strconv.Itoa(42)
	fmt.Printf("Itoa: %q (type: %s)\n", s, reflect.TypeOf(s))

	num, err := strconv.Atoi("789")
	if err == nil {
		fmt.Printf("Atoi: %d (type: %s)\n", num, reflect.TypeOf(num))
	}

	// Float formatting
	fs := strconv.FormatFloat(3.14159, 'f', 3, 64)
	fmt.Println("FormatFloat:", fs)
}
